//! `jsrt::sort` against `fixtures/sort.json`, generated by Node 26.
//!
//! Each case rebuilds node's input and comparator from a seed with the same
//! PRNG, then checks the number of comparator calls, a hash of every call's
//! arguments in order, and the resulting permutation. Comparators include
//! random results and non-transitive ones, so the permutation only matches if
//! the call sequence matches V8's.

mod common;

use common::*;
use jsrt::sort::{sort_by, sort_strings};

/// mulberry32, as in `fixtures/gen.mjs`.
struct Rng(u32);

impl Rng {
    fn next(&mut self) -> u32 {
        self.0 = self.0.wrapping_add(0x6D2B_79F5);
        let mut t = self.0;
        t = (t ^ (t >> 15)).wrapping_mul(t | 1);
        t ^= t.wrapping_add((t ^ (t >> 7)).wrapping_mul(t | 61));
        t ^ (t >> 14)
    }

    fn int(&mut self, n: u32) -> u32 {
        self.next() % n
    }
}

fn count(n: usize) -> f64 {
    f64::from(u32::try_from(n).unwrap())
}

/// `SORT_MODES` in `fixtures/gen.mjs`. Values are JS numbers.
fn values(mode: &str, r: &mut Rng, n: usize) -> Vec<f64> {
    let n32 = u32::try_from(n).unwrap();
    match mode {
        "random2" => (0..n).map(|_| f64::from(r.int(2))).collect(),
        "random10" => (0..n).map(|_| f64::from(r.int(10))).collect(),
        "randomN" => (0..n).map(|_| f64::from(r.int(n32))).collect(),
        "randomBig" => (0..n).map(|_| f64::from(r.next())).collect(),
        "sorted" => (0..n).map(count).collect(),
        "reversed" => (0..n).map(|i| count(n - i)).collect(),
        "runs" => {
            let mut out = Vec::new();
            while out.len() < n {
                let len = 1 + r.int(200);
                let start = f64::from(r.int(1000));
                let desc = r.int(2) == 1;
                for i in 0..len {
                    if out.len() >= n {
                        break;
                    }
                    let i = f64::from(i);
                    out.push(if desc { start - i } else { start + i });
                }
            }
            out
        }
        "sawtooth" => {
            let k = 1 + r.int(50);
            (0..n32).map(|i| f64::from(i % k)).collect()
        }
        _ => panic!("unknown mode {mode}"),
    }
}

/// `SORT_KINDS` in `fixtures/gen.mjs`.
fn compare(kind: &str, a: f64, b: f64, rc: &mut Rng) -> f64 {
    match kind {
        "consistent" => a - b,
        "descending" => b - a,
        "random" => f64::from(rc.next() % 3) - 1.0,
        "rockPaperScissors" => [0.0, 1.0, -1.0][[0.0, 1.0, 2.0]
            .iter()
            .position(|&m| m == ((a - b) % 3.0 + 3.0) % 3.0)
            .unwrap()],
        "literalsReturnOne" => {
            if a % 2.0 != 0.0 && b % 2.0 != 0.0 {
                1.0
            } else {
                a - b
            }
        }
        "fractionOrNaN" => {
            if a % 7.0 == b % 7.0 {
                f64::NAN
            } else {
                (a - b) / 3.0
            }
        }
        "alwaysOne" => 1.0,
        "alwaysMinusOne" => -1.0,
        "alwaysZero" => 0.0,
        _ => panic!("unknown kind {kind}"),
    }
}

const FNV_OFFSET: u32 = 2_166_136_261;

fn fnv(h: u32, x: usize) -> u32 {
    (h ^ u32::try_from(x).unwrap()).wrapping_mul(16_777_619)
}

#[test]
fn comparator_calls_match_v8() {
    let f = fixture("sort.json");
    for case in arr(&f["cases"]) {
        let seed = u32::try_from(int(&case[0])).unwrap();
        let mode = case[1].as_str().unwrap();
        let kind = case[2].as_str().unwrap();
        let n = usize::try_from(int(&case[3])).unwrap();
        let ctx = format!("seed={seed} mode={mode} kind={kind} n={n}");

        let vals = values(mode, &mut Rng(seed), n);
        let mut rc = Rng(seed ^ 0x5BD1_E995);
        let mut ids: Vec<usize> = (0..n).collect();
        let mut calls = 0;
        let mut call_hash = FNV_OFFSET;
        sort_by(&mut ids, |&a, &b| {
            calls += 1;
            call_hash = fnv(fnv(call_hash, a), b);
            compare(kind, vals[a], vals[b], &mut rc)
        });

        assert_eq!(calls, int(&case[4]), "comparator calls, {ctx}");
        assert_eq!(
            i64::from(call_hash),
            int(&case[5]),
            "comparator call hash, {ctx}"
        );
        if case[7].is_array() {
            let want: Vec<usize> = arr(&case[7])
                .iter()
                .map(|v| usize::try_from(int(v)).unwrap())
                .collect();
            assert_eq!(ids, want, "result, {ctx}");
        }
        let result_hash = ids.iter().fold(FNV_OFFSET, |h, &x| fnv(h, x));
        assert_eq!(i64::from(result_hash), int(&case[6]), "result hash, {ctx}");
    }
}

#[test]
fn default_string_sort() {
    let f = fixture("sort.json");
    for case in arr(&f["strings"]) {
        let mut input: Vec<String> = arr(&case[0])
            .iter()
            .map(|v| v.as_str().unwrap().to_owned())
            .collect();
        let want: Vec<&str> = arr(&case[1]).iter().map(|v| v.as_str().unwrap()).collect();
        sort_strings(&mut input);
        assert_eq!(input, want);
    }
}
